const item = $input.first().json;
const body = item.body || item;
const msg = body.message || {};
const call = (msg.toolCallList && msg.toolCallList[0]) || (msg.toolCalls && msg.toolCalls[0]) || {};
let args = call.arguments || (call.function && call.function.arguments) || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
// Fallback so you can test with a plain {"phone": "...", "zip_code": "..."} body
const src = Object.keys(args).length ? args : body;
return [{ json: {
  toolCallId: call.id || 'manual-test',
  phone: String(src.phone || ''),
  zip: String(src.zip_code || '')
} }];

const { toolCallId, phone } = $('Parse Lookup').first().json;
const digits = s => String(s || '').replace(/\D/g, '').slice(-10);
const rows = $input.all().map(i => i.json);
let result;
if (rows.length === 0 || rows[0].error) {
  result = { error: true, message: 'lookup_failed' };
} else {
  const want = digits(phone);
  const row = want.length === 10 ? rows.find(r => digits(r.phone) === want) : null;
  result = row ? { found: true, first_name: String(row.full_name).split(' ')[0] } : { found: false };
}
return [{ json: { response: { results: [{ toolCallId, result: JSON.stringify(result) }] } } }];

