const { toolCallId, phone, zip } = $('Parse Verify').first().json;
const digits = s => String(s || '').replace(/\D/g, '').slice(-10);
const zipNorm = s => String(s || '').replace(/\D/g, '').padStart(5, '0');
const customers = $('Read Customers 2').all().map(i => i.json);
const claims = $input.all().map(i => i.json);
let result;
if (customers.length === 0 || customers[0].error) {
  result = { error: true, message: 'lookup_failed' };
} else {
  const want = digits(phone);
  const cust = want.length === 10 ? customers.find(r => digits(r.phone) === want) : null;
  if (!cust || zipNorm(cust.zip_code) !== zipNorm(zip)) {
    // Same answer for unknown phone and wrong ZIP: never reveal which one failed
    result = { verified: false };
  } else {
    const claim = claims.find(c => digits(c.phone) === want);
    if (!claim) {
      result = { verified: true, full_name: cust.full_name, has_claim: false };
    } else {
      result = {
        verified: true,
        full_name: cust.full_name,
        has_claim: true,
        claim_id: claim.claim_id,
        claim_type: claim.claim_type,
        status: claim.status,
        last_updated: claim.last_updated,
        docs_required: String(claim.docs_required).toLowerCase() === 'yes',
        docs_needed_description: claim.docs_needed_description || '',
        adjuster_note: claim.adjuster_note || ''
      };
    }
  }
}
return [{ json: { response: { results: [{ toolCallId, result: JSON.stringify(result) }] } } }];
